/* Copy row 'r' into buffer 'out' (out must have space for FEATURE_COUNT elements). */
static inline void get_normalized_row(size_t r, float *out, size_t n) {
    if (n < FEATURE_COUNT) return;
    if (r >= (size_t)ROW_COUNT) return;
    for (size_t i = 0; i < (size_t)FEATURE_COUNT; ++i) out[i] = NORMALIZED_DATA[r][i];
}

